    static void field(JComponent c){ c.setFont(font(14,false));c.setForeground(INK);c.setBackground(WHITE);c.setPreferredSize(new Dimension(210,42));c.setMinimumSize(new Dimension(90,38)); if(c instanceof JTextComponent){JTextComponent t=(JTextComponent)c;t.setBorder(new CompoundBorder(new LineBorder(LINE,1,true),pad(8,11,8,11)));t.setCaretColor(TEAL);if(!t.isEditable())t.setBackground(BG);t.addFocusListener(new java.awt.event.FocusAdapter(){public void focusGained(java.awt.event.FocusEvent e){t.setBorder(new CompoundBorder(new LineBorder(TEAL,1,true),pad(8,11,8,11)));}public void focusLost(java.awt.event.FocusEvent e){t.setBorder(new CompoundBorder(new LineBorder(LINE,1,true),pad(8,11,8,11)));}});} }
