    static class Glyph implements Icon {String kind;int size;Color color;Glyph(String k,int s,Color c){kind=k;size=s;color=c;}public int getIconWidth(){return size;}public int getIconHeight(){return size;}public void paintIcon(Component c,Graphics g,int x,int y){Graphics2D a=(Graphics2D)g.create();a.translate(x,y);a.scale(size/40.0,size/40.0);a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);a.setColor(color);a.setStroke(new BasicStroke(2.4f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));switch(kind){case "cross":a.fillRoundRect(15,3,10,34,5,5);a.fillRoundRect(3,15,34,10,5,5);break;case "people":a.drawOval(14,5,12,12);a.drawRoundRect(8,22,24,13,9,9);break;case "pill":a.rotate(-Math.PI/4,20,20);a.drawRoundRect(11,3,18,34,18,18);a.drawLine(11,20,29,20);break;case "lock":a.drawRoundRect(9,17,22,19,4,4);a.drawArc(14,4,12,20,0,180);a.drawLine(20,24,20,29);break;case "pay":a.drawRoundRect(4,9,32,23,5,5);a.drawLine(5,17,35,17);a.drawLine(10,25,17,25);break;default:a.drawRoundRect(9,5,22,30,4,4);a.drawLine(14,14,26,14);a.drawLine(14,20,26,20);a.drawLine(14,26,23,26);}a.dispose();}}
    static String titleFor(String n){switch(n){case "EntryFrame":return "Welcome";case "LoginFrame":return "Sign in";case "SignUpFrame":return "Create your account";case "ForgetPassFrame":return "Reset password";case "OwnerHomeFrame":return "Admin dashboard";case "EmployeeHomeFrame":return "Employee dashboard";case "CustomerHomeFrame":return "Customer dashboard";case "OwnerAllPayment":return "All payments";case "CustomerSelfPaymentListFrame":return "Payment history";case "CustomerBuyMedicineFrame":return "Medicine shop";case "BuyFrame":return "Checkout";case "MedicineListFrame2":return "Medicine inventory";case "MedicineListFrame":return "Medicine inventory";case "OrderLineListFrame":return "Order items";default:return n.replace("Frame","").replaceAll("[0-9]+$","").replaceAll("([a-z])([A-Z])","$1 $2").replace("Operation","management").replace("Update Profile","profile").replace("Update Password","password");}}
    public static void install(JFrame f,JPanel old){
        List<JComponent> controls=new ArrayList<>();collect(old,controls);
        String name=f.getClass().getSimpleName(), title=titleFor(name);f.setTitle("Error Pharma  |  "+title);
        List<JButton> buttons=new ArrayList<>();JButton back=null;JScrollPane table=null;
        for(JComponent c:controls){if(c instanceof JButton){JButton b=(JButton)c; if(back(b))back=b;else buttons.add(b);}else if(c instanceof JScrollPane && ((JScrollPane)c).getViewport().getView() instanceof JTable)table=(JScrollPane)c;}
        if(back!=null)style(back,false);
        JPanel root=panel(new BorderLayout(),BG);
        if(name.equals("EntryFrame")||name.equals("LoginFrame")){root.add(auth(name,controls,buttons,back,f),BorderLayout.CENTER);}
        else {JPanel top=panel(new BorderLayout(),BG);top.setBorder(pad(16,24,14,24));top.add(brand(false),BorderLayout.WEST);if(back!=null){if(name.endsWith("HomeFrame"))back.setText("Sign out");top.add(back,BorderLayout.EAST);}root.add(top,BorderLayout.NORTH);
            JPanel main=vertical(BG);main.setBorder(pad(8,26,24,26));add(main,label(title,30,INK,true));space(main,5);add(main,label(subtitle(name),14,MUTED,false));space(main,22);
            if(name.endsWith("HomeFrame"))dashboard(main,name,buttons);
            else if(table!=null){JPanel content=panel(new BorderLayout(0,18),BG);content.add(main,BorderLayout.NORTH);content.add(tableView(table,buttons),BorderLayout.CENTER);root.add(content,BorderLayout.CENTER);main.setBorder(pad(8,26,0,26));}
            else if(name.equals("CustomerBuyMedicineFrame"))shop(main,controls,buttons);
            else if(name.equals("BuyFrame")){JPanel p=vertical(WHITE);p.setBorder(new CompoundBorder(new LineBorder(LINE,1,true),pad(30,30,30,30)));for(JComponent c:controls)if(c instanceof JLabel){JLabel l=(JLabel)c;l.setText(l.getText().replace("Your selected Total Medicine Price","Total medicine price: "));l.setFont(font(25,true));l.setForeground(INK);add(p,l);}space(p,24);add(p,actions(buttons));add(main,p);}
            else form(main,controls,buttons,name);
            if(table==null)root.add(scroll(main),BorderLayout.CENTER);
        }
        f.setContentPane(root);f.setMinimumSize(new Dimension(760,520));f.setSize(1100,740);f.setLocationRelativeTo(null);f.setResizable(true);
    }
    static String subtitle(String n){if(n.endsWith("HomeFrame"))return "Your pharmacy workspace. Choose a service to get started.";if(n.contains("List")||n.equals("OwnerAllPayment"))return "Browse, search and sort the available records.";if(n.contains("Operation"))return "Manage records using the details and actions below.";if(n.equals("CustomerBuyMedicineFrame"))return "Select medicines, enter quantities and continue to checkout.";if(n.equals("BuyFrame"))return "Review the total before recording your payment.";return "Enter or review the information below.";}
