        if(back!=null){add(body,back);space(body,12);}space(body,10);add(body,label("LOCAL DESKTOP  /  JAVA SWING",11,MUTED,true));GridBagConstraints gc=new GridBagConstraints();gc.weightx=1;gc.fill=GridBagConstraints.HORIZONTAL;gc.insets=new Insets(0,30,0,30);right.add(body,gc);split.add(scroll(right));return split;
