    static class Hero extends JPanel {Hero(){setBackground(NAVY);setLayout(new BorderLayout());JPanel content=vertical(NAVY);content.setOpaque(false);content.setBorder(pad(36,36,32,36));JPanel b=brand(true);b.setOpaque(false);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,38));PharmaUI.add(content,b);space(content,36);PharmaUI.add(content,label("A better way to",34,WHITE,true));PharmaUI.add(content,label("manage care.",34,new Color(154,233,207),true));space(content,16);PharmaUI.add(content,label("Inventory  /  People  /  Payments",14,new Color(185,214,217),false));content.add(Box.createVerticalGlue());PharmaUI.add(content,label("ERROR PHARMA   /   WORKSPACE",12,new Color(185,214,217),true));add(content,BorderLayout.CENTER);} @Override protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int w=getWidth(),h=getHeight();a.setPaint(new GradientPaint(0,0,NAVY,w,h,new Color(17,100,95)));a.fillRect(0,0,w,h);a.setColor(new Color(255,255,255,16));for(int i=0;i<6;i++){int r=110+i*40;a.drawOval(w/2-r,h*2/3-r,r*2,r*2);}a.translate(w/2.0,h*0.68);a.rotate(-0.65);a.setColor(new Color(158,232,208));a.fillRoundRect(-72,-34,144,68,68,68);a.setColor(new Color(242,255,250));a.fillRoundRect(-72,-34,75,68,68,68);a.fillRect(-36,-34,36,68);a.setColor(new Color(30,117,109));a.drawLine(0,-33,0,33);a.rotate(.65);a.setColor(new Color(255,255,255,105));a.fillRoundRect(108,-94,12,50,5,5);a.fillRoundRect(89,-75,50,12,5,5);a.dispose();}}
    static JPanel adaptiveGrid(int cols,int gap){JPanel p=panel(new GridLayout(0,cols,gap,gap),BG);p.addComponentListener(new java.awt.event.ComponentAdapter(){public void componentResized(java.awt.event.ComponentEvent e){GridLayout l=(GridLayout)p.getLayout();int n=p.getWidth()<850?2:cols;if(l.getColumns()!=n){l.setColumns(n);p.revalidate();}}});return p;}
    static String iconFor(String t){String s=t.toLowerCase();if(s.contains("password"))return "lock";if(s.contains("medicine"))return "pill";if(s.contains("payment"))return "pay";if(s.contains("owner")||s.contains("customer")||s.contains("employee")||s.contains("profile"))return "people";return "list";}
